INSERT INTO device_software (device_id, name, version, vendor) SELECT d.id, s.n, s.v, s.p FROM devices d JOIN (SELECT '7-Zip 24.09 (x64)' AS n, '24.09' AS v, 'Igor Pavlov' AS p UNION ALL SELECT 'Microsoft 365 Apps for business - de-de' AS n, '16.0.19127.20154' AS v, 'Microsoft Corporation' AS p UNION ALL SELECT 'Mozilla Firefox (x64 de)' AS n, '144.0' AS v, 'Mozilla' AS p UNION ALL SELECT 'VLC media player' AS n, '3.0.21' AS v, 'VideoLAN' AS p) s WHERE d.inventory_no = 'INV-0001' AND NOT EXISTS (SELECT 1 FROM device_software x WHERE x.device_id = d.id);
